using AlshrouqSchool.Domain.Contracts; using AlshrouqSchool.Domain.Entities.MediaAndContentModule; using AlshrouqSchool.Shared.DTOs.Gallery.Common; using AlshrouqSchool.Shared.DTOs.Gallery.Posts; using AutoMapper; using MediatR;
namespace AlshrouqSchool.Application.Features.Gallery.Queries.Posts;
public sealed record GetAllPostsQuery(PostQueryParameters Parameters):IRequest<PagedResult<PostSummaryDto>>; public sealed record GetPostByIdQuery(int Id):IRequest<PostDto?>; public sealed record GetPostBySlugQuery(string Slug):IRequest<PostDto?>; public sealed record GetPublishedPostsQuery(PostQueryParameters Parameters):IRequest<PagedResult<PostSummaryDto>>;
public sealed class GetAllPostsQueryHandler(IUnitOfWork u,IMapper m):IRequestHandler<GetAllPostsQuery,PagedResult<PostSummaryDto>>{public async Task<PagedResult<PostSummaryDto>> Handle(GetAllPostsQuery r,CancellationToken ct)=>await PostPaging.Create(u,m,r.Parameters,false);}
public sealed class GetPublishedPostsQueryHandler(IUnitOfWork u,IMapper m):IRequestHandler<GetPublishedPostsQuery,PagedResult<PostSummaryDto>>{public async Task<PagedResult<PostSummaryDto>> Handle(GetPublishedPostsQuery r,CancellationToken ct)=>await PostPaging.Create(u,m,r.Parameters,true);}
public sealed class GetPostByIdQueryHandler(IUnitOfWork u,IMapper m):IRequestHandler<GetPostByIdQuery,PostDto?>{public async Task<PostDto?> Handle(GetPostByIdQuery r,CancellationToken ct){var e=await u.GetRepository<Post,int>().GetByIdAsync(r.Id);return e is null||e.IsDeleted?null:m.Map<PostDto>(e);}}
public sealed class GetPostBySlugQueryHandler(IUnitOfWork u,IMapper m):IRequestHandler<GetPostBySlugQuery,PostDto?>{public async Task<PostDto?> Handle(GetPostBySlugQuery r,CancellationToken ct){var e=(await u.GetRepository<Post,int>().GetAllAsync()).FirstOrDefault(x=>!x.IsDeleted&&x.Slug==r.Slug.Trim().ToLowerInvariant());return e is null?null:m.Map<PostDto>(e);}}
internal static class PostPaging{public static async Task<PagedResult<PostSummaryDto>> Create(IUnitOfWork u,IMapper m,PostQueryParameters p,bool published){var all=await u.GetRepository<Post,int>().GetAllAsync();var q=all.Where(x=>!x.IsDeleted&&(!published||(x.IsPublished&&x.PublishedAtUtc<=DateTime.UtcNow)));if(p.Type.HasValue)q=q.Where(x=>x.Type==p.Type);if(!string.IsNullOrWhiteSpace(p.Search))q=q.Where(x=>x.Title.Contains(p.Search,StringComparison.OrdinalIgnoreCase));var total=q.Count();var page=Math.Max(1,p.PageNumber);var size=Math.Clamp(p.PageSize,1,100);return new(m.Map<List<PostSummaryDto>>(q.OrderBy(x=>x.DisplayOrder).Skip((page-1)*size).Take(size)),page,size,total);}}